const markGameExportComplete = `-- name: MarkGameExportComplete :one
UPDATE game_exports
SET status = 'complete',
    storage_path = $2,
    size_bytes = $3,
    file_count = $4,
    content_fingerprint = $5,
    progress_note = NULL,
    completed_at = NOW(),
    expires_at = NOW() + $6::interval
WHERE id = $1
RETURNING id, game_id, requested_by_user_id, status, content_fingerprint, storage_path, size_bytes, file_count, error_message, progress_note, started_at, completed_at, expires_at, created_at
`

type MarkGameExportCompleteParams struct {
	ID                 int32           `json:"id"`
	StoragePath        pgtype.Text     `json:"storage_path"`
	SizeBytes          pgtype.Int8     `json:"size_bytes"`
	FileCount          pgtype.Int4     `json:"file_count"`
	ContentFingerprint pgtype.Text     `json:"content_fingerprint"`
	RetentionPeriod    pgtype.Interval `json:"retention_period"`
}

// retention_period sets how long the artifact is kept before the sweep
// reclaims it; the row itself is retained as history.
func (q *Queries) MarkGameExportComplete(ctx context.Context, arg MarkGameExportCompleteParams) (GameExport, error) {
	row := q.db.QueryRow(ctx, markGameExportComplete,
		arg.ID,
		arg.StoragePath,
		arg.SizeBytes,
		arg.FileCount,
		arg.ContentFingerprint,
		arg.RetentionPeriod,
	)
	var i GameExport
	err := row.Scan(
		&i.ID,
		&i.GameID,
		&i.RequestedByUserID,
		&i.Status,
		&i.ContentFingerprint,
		&i.StoragePath,
		&i.SizeBytes,
		&i.FileCount,
		&i.ErrorMessage,
		&i.ProgressNote,
		&i.StartedAt,
		&i.CompletedAt,
		&i.ExpiresAt,
		&i.CreatedAt,
	)
	return i, err
}

const markGameExportExpired = `-- name: MarkGameExportExpired :exec
UPDATE game_exports
SET storage_path = NULL
WHERE id = $1
`

// Clears the artifact pointer after the file has been deleted from storage.
// The row is kept so export history survives; size/file counts stay for
// reference. Regeneration happens on the next request.
func (q *Queries) MarkGameExportExpired(ctx context.Context, id int32) error {
	_, err := q.db.Exec(ctx, markGameExportExpired, id)
	return err
}

