const requeueStalledGameExports = `-- name: RequeueStalledGameExports :execrows
UPDATE game_exports
SET status = 'pending', started_at = NULL, progress_note = NULL
WHERE status = 'running'
  AND started_at < NOW() - $1::interval
`

// Startup crash recovery: return jobs left 'running' by a dead process to
// 'pending'. Bounded by age so a job actively running elsewhere is untouched.
func (q *Queries) RequeueStalledGameExports(ctx context.Context, staleAfter pgtype.Interval) (int64, error) {
	result, err := q.db.Exec(ctx, requeueStalledGameExports, staleAfter)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
